    private void ensureCapacity(int capacity) {
        if (capacity > data.length) {
            int newSize = Math.max(data.length * 2, capacity);
            data = Arrays.copyOf(data, newSize);
        }
    }

    public byte[] getData() {
        return Arrays.copyOf(data, length);
    }

    public int getLength() {
        return length;
    }
}

